<h2>Preview your search snippet</h2><p class="lead">Test how a page title and description may look before publishing.</p><div class="form-grid"><div class="field full"><label for="title">SEO title</label><input id="title" maxlength="120" value="Free Online Tools for Better Workflows"><div class="counter-row"><span>Typical desktop target: about 50–60 characters</span><span id="tc">0</span></div><div class="progress"><span id="tp"></span></div></div><div class="field full"><label for="pageUrl">Page URL</label><input id="pageUrl" type="url" value="https://toolboxkart.tech/seo/serp-preview"></div><div class="field full"><label for="desc">Meta description</label><textarea id="desc" maxlength="260">Preview a title, URL and meta description in a clean Google-style search result before you publish.</textarea><div class="counter-row"><span>Typical target: about 140–160 characters</span><span id="dc">0</span></div><div class="progress"><span id="dp"></span></div></div></div><div class="result-box"><div class="serp-preview"><div class="serp-url" id="pu"></div><div class="serp-title" id="pt"></div><div class="serp-desc" id="pd"></div></div></div>
<script>(()=>{const $=id=>document.getElementById(id),t=$('title'),u=$('pageUrl'),d=$('desc');function p(el,val,max){el.textContent=val.length+' characters';const bar=el.id==='tc'?$('tp'):$('dp');bar.style.width=Math.min(100,val.length/max*100)+'%';bar.style.background=val.length>max?'var(--danger)':val.length>max*.8?'var(--success)':'var(--warning)'}function go(){$('pt').textContent=t.value||'Your page title';$('pd').textContent=d.value||'Your meta description will appear here.';try{const x=new URL(u.value);$('pu').textContent=x.hostname+' › '+x.pathname.split('/').filter(Boolean).join(' › ')}catch(e){$('pu').textContent=u.value||'example.com'}p($('tc'),t.value,60);p($('dc'),d.value,160)}[t,u,d].forEach(x=>x.addEventListener('input',go));go()})();</script>
